using System.Xml.Linq;
DirectoryInfo? root=new(AppContext.BaseDirectory);while(root!=null&&!File.Exists(Path.Combine(root.FullName,"src/Captovix/MainWindow.xaml")))root=root.Parent;
if(root==null)throw new Exception("Source root missing.");
var doc=XDocument.Load(Path.Combine(root.FullName,"src/Captovix/MainWindow.xaml"));XNamespace w="http://schemas.microsoft.com/winfx/2006/xaml/presentation",x="http://schemas.microsoft.com/winfx/2006/xaml";int n=0;
void Check(bool b,string s){if(!b)throw new Exception(s);n++;Console.WriteLine("PASS: "+s);}XElement Named(string name)=>doc.Descendants().Single(e=>(string?)e.Attribute(x+"Name")==name);
var stage=Named("SettingsStaging");var inspector=Named("InspectorPane");
Check(doc.Root!.Attribute("WindowState")?.Value=="Maximized","Editor default remains maximized");
Check(doc.Descendants(w+"Menu").Single().Elements(w+"MenuItem").Count()==6,"Six conventional top-level menu modules");
Check(doc.Descendants(w+"MenuItem").Any(e=>e.Elements(w+"MenuItem").Any(child=>child.Elements(w+"MenuItem").Any())),"Menu exposes hierarchical submodules");
foreach(var name in new[]{"CaptureSettingsView","UpdatesExpander","MetadataSettingsView","DiagnosticsSettingsView"})Check(Named(name).Ancestors().Contains(stage)&&!Named(name).Ancestors().Contains(inspector),"System module belongs to modal staging, not inspector: "+name);
Check(stage.Attribute("Visibility")?.Value=="Collapsed","Unopened system controls consume no workspace area");
var tags=Named("ToolBox").Elements(w+"Button").Select(b=>(string?)b.Attribute("Tag")).ToArray();Check(tags.Count(t=>t=="Arrow")==1&&tags.Count(t=>t=="Shape")==1,"One arrow group and one shape group");Check(!tags.Intersect(new[]{"Line","Rectangle","Ellipse","Cover"}).Any(),"No duplicate line/frame/ellipse or Cover tool button");
Check(tags.Contains("PixelRectangle"),"Pixel selection enters from compact toolbar");
Check(Named("CalloutKindPicker").Attribute("Visibility")?.Value=="Collapsed"&&Named("CalloutKindPicker").Elements().Count()==10&&Named("CalloutTileGrid").Name==w+"WrapPanel","Ten callout styles use preview host, not visible combo");
Check(Named("ShapeArrowTip").Elements().Count()==5,"Arrow group includes headless line choice");
foreach(var name in new[]{"CaptureButton","RecordButton"})Check(Named(name).Attribute("Padding")?.Value=="9,4","Compact capture/record action: "+name);
Check(Named("MediaList").Attribute("SelectionChanged")?.Value=="Media_Changed"&&Named("MediaList").Attribute("VirtualizingPanel.IsVirtualizing")?.Value=="True","Library preserves selection routing and virtualization");
Check(Named("RestoreMediaButton").Attribute("Content")?.Value=="↶","Restore action is an icon at library footer");
Check(doc.Descendants().Where(e=>e.Attribute(x+"Name")!=null).Select(e=>e.Attribute(x+"Name")!.Value).Distinct().Count()==doc.Descendants().Count(e=>e.Attribute(x+"Name")!=null),"Named WPF controls are unique across editor and modal modules");
Console.WriteLine($"{n} shell layout structure checks passed; rendering still requires Windows.");
